708	     3	const MATRIX_SIZE = 5;
709	     4	const CENTER = Math.floor(MATRIX_SIZE / 2);
710	     5	const RING_PATH: readonly number[] = [1, 2, 3, 9, 14, 19, 23, 22, 21, 15, 10, 5];
711	     6	
712	     7	const DOTS = Array.from({ length: MATRIX_SIZE * MATRIX_SIZE }, (_, index) => {
713	     8		const row = Math.floor(index / MATRIX_SIZE);
714	     9		const col = index % MATRIX_SIZE;
715	    10		const distance = Math.hypot(row - CENTER, col - CENTER);
716	    11		const ringOrder = RING_PATH.indexOf(index);
717	    12	
718	    13		return {
719	    14			isCenter: row === CENTER && col === CENTER,
720	    15			isVisible: distance <= CENTER,
721	    16			ringOrder,
722	    17		};
723	    18	});
