745	    40					"grid-template-rows": `repeat(${MATRIX_SIZE}, ${dotSize()}px)`,
746	    41					gap: `${gap()}px`,
747	    42					width: `${size()}px`,
748	    43					height: `${size()}px`,
749	    44				}}
750	    45			>
751	    46				<For each={DOTS}>
752	    47					{(dot) => (
