     8	export function normalizeDomain(input: string): string | null {
     9		const trimmed = input.trim();
    10		if (!trimmed) return null;
    11		const withoutScheme = trimmed.includes("://") ? (trimmed.split("://")[1] ?? "") : trimmed;
    12		const hostWithPort = withoutScheme.split("/")[0]?.split("?")[0]?.split("#")[0]?.split("@").pop();
    13		if (!hostWithPort) return null;
    14		const host = hostWithPort.split(":")[0]?.trim() ?? "";
    15		if (!host) return null;
    16		const lowered = host.toLowerCase().replace(/^\.+|\.+$/g, "");
    17		if (!lowered) return null;
    18		const stripped = lowered.startsWith("www.") ? lowered.slice(4) : lowered;
    19		return stripped || null;
    20	}
