    19				setOpen(false);
    20			}
    21		};
    22	
    23		createEffect(() => {
    24			if (open()) {
    25				document.addEventListener("click", handleClickOutside);
    26				setHighlighted(Math.max(0, STYLE_LIST.indexOf(props.value)));
    27			} else {
    28				document.removeEventListener("click", handleClickOutside);
    29			}
    30		});
    31	
    32		onCleanup(() => {
    33			document.removeEventListener("click", handleClickOutside);
    34		});
    35	
    36		const handleKeyDown = (e: KeyboardEvent) => {
    37			if (e.key === "ArrowDown") {
    38				e.preventDefault();
    39				if (!open()) {
    40					setOpen(true);
    41					return;
    42				}
    43				setHighlighted((i) => Math.min(STYLE_LIST.length - 1, i + 1));
    44			} else if (e.key === "ArrowUp") {
    45				e.preventDefault();
    46				if (!open()) {
    47					setOpen(true);
    48					return;
    49				}
    50				setHighlighted((i) => Math.max(0, i - 1));
    51			} else if (e.key === "Enter" || e.key === " ") {
    52				if (!open()) {
    53					e.preventDefault();
