    33	
    34			const isToday =
    35				date.getDate() === today.getDate() &&
    36				date.getMonth() === today.getMonth() &&
    37				date.getFullYear() === today.getFullYear();
    38	
    39			const isYesterday =
    40				date.getDate() === yesterday.getDate() &&
    41				date.getMonth() === yesterday.getMonth() &&
    42				date.getFullYear() === yesterday.getFullYear();
