    46					<span class="truncate">{selectedLabel()}</span>
    47					<ChevronDown
    48						class={`w-4 h-4 ml-2 text-txt-muted transition-transform ${isOpen() ? "rotate-180" : ""}`}
    49					/>
    50				</button>
    51	
    52				<Show when={isOpen()}>
    53					<div class="absolute z-50 w-full mt-1 bg-th-surface border border-border-strong max-h-60 overflow-auto">
    54						<For each={props.options}>
    55							{(option) => (
    56								<button
    57									type="button"
    58									onClick={() => {
    59										props.onChange(option.value);
    60										setIsOpen(false);
    61									}}
    62									class={`flex items-center justify-between w-full px-4 py-2.5 text-left hover:bg-th-hover transition-colors font-mono text-sm ${
    63										option.value === props.value ? "text-ac bg-th-hover" : "text-txt-primary"
    64									}`}
    65								>
