     1	import { Result } from "better-result";
     2	import { For, Show, createSignal, onMount } from "solid-js";
     3	import { useI18n } from "../i18n";
     4	import {
     5		type DictionaryWord,
     6		addDictionaryWord,
     7		deleteDictionaryWord,
     8		listDictionaryWords,
     9		updateDictionaryWord,
    10	} from "../lib/commands/dictionary";
    11	import { capture } from "../lib/posthog";
    12	
    13	export default function DictionaryDefault() {
    14		const [t] = useI18n();
    15		const [words, setWords] = createSignal<DictionaryWord[]>([]);
    16		const [newWord, setNewWord] = createSignal("");
    17		const [adding, setAdding] = createSignal(false);
    18		const [editingId, setEditingId] = createSignal<string | null>(null);
    19		const [editingWord, setEditingWord] = createSignal("");
    20	
    21		const fetchWords = async () => {
    22			const result = await listDictionaryWords();
    23			if (Result.isOk(result)) setWords(result.value);
    24		};
    25	
    26		onMount(() => {
    27			capture("$pageview", { $current_url: "/dictionary" });
    28			fetchWords();
    29		});
    30	
    31		const handleAdd = async () => {
    32			const word = newWord().trim();
    33			if (!word || adding()) return;
    34	
    35			setAdding(true);
    36			const result = await addDictionaryWord(word);
    37			if (Result.isOk(result)) {
    38				capture("dictionary_word_added");
    39				await fetchWords();
    40				setNewWord("");
    41			}
    42			setAdding(false);
    43		};
    44	
    45		const handleKeyDown = (e: KeyboardEvent) => {
    46			if (e.key === "Enter") handleAdd();
    47		};
    48	
    49		const handleDelete = async (id: string) => {
    50			capture("dictionary_word_deleted");
    51			setWords(words().filter((w) => w.id !== id));
    52			const result = await deleteDictionaryWord(id);
    53			if (Result.isError(result)) await fetchWords();
    54		};
    55	
    56		const startEdit = (word: DictionaryWord) => {
    57			setEditingId(word.id);
    58			setEditingWord(word.word);
    59		};
    60	
    61		const cancelEdit = () => {
    62			setEditingId(null);
    63			setEditingWord("");
    64		};
    65	
    66		const handleEdit = async (id: string) => {
    67			const word = editingWord().trim();
    68			if (!word) return;
    69	
    70			capture("dictionary_word_edited");
    71			setWords(words().map((w) => (w.id === id ? { ...w, word } : w)));
    72			setEditingId(null);
    73			setEditingWord("");
    74	
    75			const result = await updateDictionaryWord(id, word);
    76			if (Result.isError(result)) await fetchWords();
    77		};
    78	
    79		const handleEditKeyDown = (e: KeyboardEvent, id: string) => {
    80			if (e.key === "Enter") handleEdit(id);
    81			else if (e.key === "Escape") cancelEdit();
    82		};
    83	
    84		return (
    85			<div>
    86				<div class="mb-4 flex items-center justify-end">
    87					<Show when={words().length > 0}>
    88						<span class="text-txt-muted font-mono text-xs uppercase">
    89							{t("dictionary.wordCount").replace("{count}", String(words().length))}
    90						</span>
    91					</Show>
    92				</div>
    93	
    94				<div class="bg-th-surface border border-border p-4 mb-6">
    95					<div class="flex gap-3">
    96						<input
    97							type="text"
    98							value={newWord()}
    99							onInput={(e) => setNewWord(e.currentTarget.value)}
   100							onKeyDown={handleKeyDown}
   101							placeholder={t("dictionary.wordPlaceholder")}
   102							class="flex-1 px-4 py-2 bg-th-input border border-border-strong text-txt-primary font-mono placeholder-txt-muted focus:outline-none focus:border-ac transition-colors"
   103						/>
   104						<button
   105							type="button"
   106							onClick={handleAdd}
   107							disabled={!newWord().trim() || adding()}
   108							class="flex items-center gap-2 px-4 py-2 bg-ac text-ac-on font-mono uppercase tracking-wider text-sm hover:bg-ac-hover disabled:opacity-50 transition-colors"
   109						>
   110							<span>+</span>
   111							{t("dictionary.addWord")}
   112						</button>
   113					</div>
   114				</div>
   115	
   116				<Show when={words().length === 0}>
   117					<div class="bg-th-surface border border-border p-12 flex flex-col items-center justify-center text-center">
   118						<div class="font-mono text-txt-muted text-sm mb-4">
   119							<span class="text-ac">[INFO]</span> NO_TERMS_FOUND
   120						</div>
   121						<p class="text-txt-secondary font-mono text-xs uppercase tracking-wide">
   122							{t("dictionary.emptyState")}
   123						</p>
   124						<p class="text-txt-muted font-mono text-xs mt-2 max-w-sm">
   125							{t("dictionary.emptyStateDescription")}
   126						</p>
   127					</div>
   128				</Show>
   129	
   130				<Show when={words().length > 0}>
   131					<div class="space-y-1">
   132						<For each={words()}>
   133							{(word) => (
   134								<div class="bg-th-surface border border-border px-4 py-3 flex items-center justify-between group hover:border-border-strong transition-colors">
   135									<Show
   136										when={editingId() === word.id}
   137										fallback={<span class="text-txt-primary font-mono">{word.word}</span>}
   138									>
   139										<input
   140											type="text"
   141											value={editingWord()}
   142											onInput={(e) => setEditingWord(e.currentTarget.value)}
   143											onKeyDown={(e) => handleEditKeyDown(e, word.id)}
   144											class="flex-1 px-2 py-1 bg-th-input border border-border-strong text-txt-primary font-mono focus:outline-none focus:border-ac transition-colors mr-4"
   145											autofocus
   146										/>
   147									</Show>
   148	
   149									<div class="flex items-center gap-2 font-mono text-xs">
   150										<Show
   151											when={editingId() === word.id}
   152											fallback={
   153												<>
   154													<button
   155														type="button"
   156														onClick={() => startEdit(word)}
   157														class="text-txt-muted hover:text-ac opacity-0 group-hover:opacity-100 transition-all uppercase tracking-wider"
   158														title={t("dictionary.edit")}
   159													>
   160														[EDIT]
   161													</button>
   162													<button
   163														type="button"
   164														onClick={() => handleDelete(word.id)}
   165														class="text-txt-muted hover:text-ac opacity-0 group-hover:opacity-100 transition-all uppercase tracking-wider"
   166														title={t("dictionary.delete")}
   167													>
   168														[DEL]
   169													</button>
   170												</>
   171											}
   172										>
   173											<button
   174												type="button"
   175												onClick={() => handleEdit(word.id)}
   176												class="text-success hover:opacity-80 uppercase tracking-wider"
   177												title={t("dictionary.save")}
   178											>
   179												[SAVE]
   180											</button>
   181											<button
   182												type="button"
   183												onClick={cancelEdit}
   184												class="text-txt-muted hover:text-txt-secondary uppercase tracking-wider"
   185												title={t("dictionary.cancel")}
   186											>
   187												[CANCEL]
   188											</button>
   189										</Show>
   190									</div>
   191								</div>
   192							)}
   193						</For>
   194					</div>
   195				</Show>
   196			</div>
   197		);
   198	}
