   222											</button>
   223											<button
   224												type="button"
   225												onClick={() => handleRemoveSite(group)}
   226												class="px-3 flex items-center text-txt-muted hover:text-ac opacity-0 group-hover:opacity-100 transition-all font-mono text-xs uppercase tracking-wider shrink-0"
   227												title={t("appInstructions.delete")}
   228											>
   229												[DEL]
   230											</button>
   231										</div>
   232										<Show when={isOpen()}>
   233											<div class="border-t border-border px-4 py-3 space-y-2">
   234												<div class="flex gap-2">
   235													<input
   236														type="text"
   237														value={wordValue()}
   238														onInput={(e) =>
   239															setNewWordBySite((prev) => ({
   240																...prev,
   241																[group.domain]: e.currentTarget.value,
   242															}))
   243														}
   244														onKeyDown={(e) => handleWordKeyDown(e, group)}
   245														placeholder={t("dictionary.wordPlaceholder")}
   246														class="flex-1 px-3 py-1.5 bg-th-input border border-border-strong text-txt-primary font-mono text-sm placeholder-txt-muted focus:outline-none focus:border-ac transition-colors"
   247													/>
   248													<button
   249														type="button"
   250														onClick={() => handleAddWord(group)}
   251														disabled={!wordValue().trim() || isAdding()}
   252														class="flex items-center gap-1 px-3 py-1.5 bg-ac text-ac-on font-mono uppercase tracking-wider text-xs hover:bg-ac-hover disabled:opacity-50 transition-colors"
   253													>
   254														<span>+</span>
   255														{t("dictionary.addWord")}
   256													</button>
   257												</div>
   258	
   259												<Show when={group.words.length > 0}>
   260													<div class="space-y-1 pt-1">
   261														<For each={group.words}>
   262															{(word) => (
   263																<div class="px-3 py-2 bg-th-input border border-border flex items-center justify-between gap-2 group/word">
   264																	<Show
   265																		when={editingWordId() === word.id}
   266																		fallback={
   267																			<span class="text-txt-primary font-mono text-sm flex-1 min-w-0 truncate">
   268																				{word.word}
   269																			</span>
   270																		}
   271																	>
   272																		<input
   273																			type="text"
   274																			value={editingWord()}
   275																			onInput={(e) => setEditingWord(e.currentTarget.value)}
   276																			onKeyDown={(e) => handleEditWordKeyDown(e, group, word.id)}
   277																			class="flex-1 px-2 py-1 bg-th-base border border-border-strong text-txt-primary font-mono text-sm focus:outline-none focus:border-ac transition-colors"
   278																			autofocus
   279																		/>
   280																	</Show>
   281																	<div class="flex items-center gap-2 font-mono text-xs shrink-0">
   282																		<Show
   283																			when={editingWordId() === word.id}
   284																			fallback={
   285																				<>
   286																					<button
   287																						type="button"
   288																						onClick={() => startEditWord(word.id, word.word)}
   289																						class="text-txt-muted hover:text-ac opacity-0 group-hover/word:opacity-100 transition-all uppercase tracking-wider"
   290																						title={t("dictionary.edit")}
   291																					>
   292																						[EDIT]
   293																					</button>
   294																					<button
   295																						type="button"
   296																						onClick={() => handleDeleteWord(group, word.id)}
   297																						class="text-txt-muted hover:text-ac opacity-0 group-hover/word:opacity-100 transition-all uppercase tracking-wider"
   298																						title={t("dictionary.delete")}
   299																					>
   300																						[DEL]
   301																					</button>
   302																				</>
   303																			}
   304																		>
   305																			<button
   306																				type="button"
   307																				onClick={() => handleEditWord(group, word.id)}
   308																				class="text-success hover:opacity-80 uppercase tracking-wider"
   309																				title={t("dictionary.save")}
   310																			>
   311																				[SAVE]
   312																			</button>
   313																			<button
   314																				type="button"
   315																				onClick={cancelEditWord}
   316																				class="text-txt-muted hover:text-txt-secondary uppercase tracking-wider"
   317																				title={t("dictionary.cancel")}
   318																			>
   319																				[CANCEL]
   320																			</button>
   321																		</Show>
   322																	</div>
   323																</div>
   324															)}
   325														</For>
   326													</div>
   327												</Show>
   328											</div>
   329										</Show>
   330									</div>
   331								);
   332							}}
   333						</For>
   334					</div>
   335				</Show>
   336			</div>
   337		);
   338	}

