     1	import { flatten, resolveTemplate, translator } from "@solid-primitives/i18n";
     2	import { createSignal } from "solid-js";
     3	import { createContext, useContext } from "solid-js";
     4	import { de } from "./translations/de";
     5	import { type Translations, en } from "./translations/en";
     6	import { es } from "./translations/es";
     7	import { fr } from "./translations/fr";
     8	import { it } from "./translations/it";
     9	import { ru } from "./translations/ru";
    10	import { zh } from "./translations/zh";
    11	
    12	export type Locale = "en" | "ru" | "es" | "zh" | "de" | "fr" | "it";
    13	
    14	const ALL_LOCALES: Locale[] = ["en", "ru", "es", "zh", "de", "fr", "it"];
    15	
    16	const dictionaries: Record<Locale, Translations> = {
    17		en,
    18		ru,
    19		es,
    20		zh,
    21		de,
    22		fr,
    23		it,
    24	};
    25	
    26	const flattenedDictionaries = {
    27		en: flatten(en),
    28		ru: flatten(ru),
    29		es: flatten(es),
    30		zh: flatten(zh),
    31		de: flatten(de),
    32		fr: flatten(fr),
    33		it: flatten(it),
    34	};
    35	
    36	export function createAppI18n(initialLocale: Locale = "en") {
    37		const [locale, setLocale] = createSignal<Locale>(initialLocale);
    38		const [dict, setDict] = createSignal(flattenedDictionaries[initialLocale]);
    39	
    40		const t = translator(() => dict(), resolveTemplate);
    41	
    42		const switchLocale = (newLocale: Locale) => {
    43			setLocale(newLocale);
    44			setDict(flattenedDictionaries[newLocale]);
    45			setStoredLocale(newLocale);
    46		};
    47	
    48		return [t, { locale, setLocale: switchLocale }] as const;
    49	}
    50	
    51	export type I18nContextType = ReturnType<typeof createAppI18n>;
    52	
    53	export const I18nCtx = createContext<I18nContextType>();
    54	
    55	export function useI18n() {
    56		const context = useContext(I18nCtx);
    57		if (!context) {
    58			throw new Error("useI18n must be used within an I18nProvider");
    59		}
    60		return context;
    61	}
    62	
    63	export function getStoredLocale(): Locale {
    64		const stored = localStorage.getItem("locale");
    65		if (stored && ALL_LOCALES.includes(stored as Locale)) {
    66			return stored as Locale;
    67		}
    68		return "en";
    69	}
    70	
    71	export function setStoredLocale(locale: Locale) {
    72		localStorage.setItem("locale", locale);
    73	}
    74	
    75	export { dictionaries };

