  src = src.replace(/^import[^;]*;/gm, '');
  src = src.replace(/export\s+type[^=]*=[^;]*;/gs, '');
  src = src.replace(/export\s+const\s+(\w+)(:\s*[\w.]+)?\s*=/, 'globalThis.__D =');
  src = src.replace(/\s+satisfies\s+\w+/g, '');
  src = src.replace(/as\s+const\s*;?\s*$/m, ';');
  eval(src);
  const dict = globalThis.__D;
  const keys = [];
  (function walk(o, prefix) {
    for (const [k,v] of Object.entries(o)) {
      const key = prefix ? prefix + '.' + k : k;
      if (v && typeof v === 'object') walk(v, key); else keys.push(key);
    }
  })(dict, '');
  return new Set(keys);
}
const dir = 'src/i18n/translations';
const en = loadKeys(path.join(dir,'en.ts'));
for (const loc of ['ru','es','zh','de','fr','it']) {
  const k = loadKeys(path.join(dir, loc + '.ts'));
  const missing = [...en].filter(x => !k.has(x));
