const fs = require('node:fs');
const path = require('node:path');
function loadDict(file) {
  let src = fs.readFileSync(file, 'utf8');
  src = src.replace(/^import[^;]*;/gm, '');
  src = src.replace(/export\s+type\s+Translations\s*=\s*\{[\s\S]*?\n\};/m, '');
  src = src.replace(/export\s+const\s+(\w+)(:\s*[\w.]+)?\s*=/, 'globalThis.__D =');
  eval(src);
  return globalThis.__D;
}
function flat(o, prefix, out) {
  for (const [k,v] of Object.entries(o)) {
    const key = prefix ? prefix + '.' + k : k;
    if (v && typeof v === 'object') flat(v, key, out); else out[key] = v;
  }
  return out;
}
const dir = 'src/i18n/translations';
const en = flat(loadDict(path.join(dir,'en.ts')), '', {});
for (const loc of ['ru','es','zh','de','fr','it']) {
  const d = flat(loadDict(path.join(dir, loc + '.ts')), '', {});
  const same = Object.keys(en).filter(k => d[k] === en[k] && en[k].length > 3 && !/^[A-Z⌘⌥⌃⇧\s]+$/.test(en[k]));
  if (same.length) console.log('== ' + loc + ' identical-to-English values (' + same.length + '): ' + same.slice(0, 25).join(', '));
  // placeholder check
  const phMismatch = Object.keys(en).filter(k => {
    const enPh = (en[k].match(/\{[^}]+\}/g) || []).sort().join();
    const locPh = ((d[k]||'').match(/\{[^}]+\}/g) || []).sort().join();
    return enPh !== locPh;
  });
  if (phMismatch.length) console.log('   placeholder mismatch: ' + phMismatch.join(', '));
}
