const fs = require('node:fs');
const path = require('node:path');
function loadDict(file) {
  let src = fs.readFileSync(file, 'utf8');
  src = src.replace(/^import[^;]*;/gm, '');
  src = src.replace(/export\s+type\s+Translations\s*=\s*\{[\s\S]*?\n\};/m, '');
  src = src.replace(/export\s+const\s+(\w+)(:\s*[\w.]+)?\s*=/, 'globalThis.__D =');
  eval(src);
  return globalThis.__D;
}
function flat(o, prefix, out) {
  for (const [k,v] of Object.entries(o)) {
    const key = prefix ? prefix + '.' + k : k;
    if (v && typeof v === 'object') flat(v, key, out); else out[key] = v;
  }
  return out;
}
const en = flat(loadDict('src/i18n/translations/en.ts'), '', {});
// gather all t(\"...\") usages
const { execSync } = require('node:child_process');
const used = new Set();
const out = execSync('grep -rhoE \'t\\\\(\\\"[a-zA-Z0-9_.]+\\\"\' src --include=*.tsx --include=*.ts', {encoding:'utf8'});
for (const line of out.split('\n')) {
  const m = line.match(/t\\(\"([^\"]+)\"/);
  if (m) used.add(m[1]);
}
const defined = new Set(Object.keys(en));
const dead = [...defined].filter(k => !used.has(k));
const undef = [...used].filter(k => !defined.has(k));
console.log('used t() keys: ' + used.size + ' / defined: ' + defined.size);
console.log('DEAD keys (' + dead.length + '): ' + dead.join(', '));
console.log('UNDEFINED used keys: ' + undef.join(', '));
"

